import {SKILLS,RANKED_SKILLS,skillRank,skillText,skillUpgradeCost,canLearn,learn,equip,upgradeSkill,canRebuild,movement,power} from './core.js';
import {TALENTS,TALENT_SIZE,TALENT_SECTORS,TALENT_EFFECTS,talentNetwork,talentRank,talentConnected,talentCost,talentText,buyTalent,refundTalent} from './talents.js';
import {progressionEffects,invalidateProgression} from './progression-effects.js';
import {skillPointCost} from './pillars.js';
import {glyph} from './ui-art.js';
const number=n=>Number(n.toFixed(2)).toLocaleString('pt-BR');
const icon=n=>n.kind==='root'?'gem':n.kind==='skill'?(n.icon?.length>2?n.icon:n.passive?'fortune':n.id):TALENT_SECTORS[n.sector].icon;
const maxRank=n=>n.kind==='root'?1:n.kind==='skill'?(RANKED_SKILLS.includes(n.id)?3:1):n.max;
export class TalentView{
 constructor(){this.selected='ear';this.zoom=.6;this.position=null;}
 markup(s,id){if(id)this.selected=id;const net=talentNetwork(SKILLS),lookup=new Map(net.nodes.map(n=>[n.id,n]));
  return `<section class="web-top"><div><h2>TEIA DE ECOS</h2></div><div class="web-points"><b>✦ ${s.experience.points}</b><span>PONTOS · NV. ${s.experience.level}</span></div></section><nav class="web-sectors" aria-label="Especializações">${TALENT_SECTORS.map((g,i)=>`<button data-sector="${i}" style="--sector:${g.color}">${glyph(g.icon)}${g.name}</button>`).join('')}</nav><div class="web-layout"><div class="web-map-wrap"><div class="web-tools"><button data-zoom="-" aria-label="Diminuir árvore">−</button><b id="webZoom">${Math.round(this.zoom*100)}%</b><button data-zoom="+" aria-label="Ampliar árvore">+</button><button id="webCenter">ORIGEM</button><details class="quiet-details"><summary>CONTROLES</summary><p>Arraste para explorar. Use + e − para aproximar.</p></details></div><div class="web-viewport" tabindex="0" aria-label="Mapa de talentos. Arraste ou use as barras de rolagem."><div class="web-size" style="width:${TALENT_SIZE*this.zoom}px;height:${TALENT_SIZE*this.zoom}px"><div class="web-canvas" style="transform:scale(${this.zoom})"><svg class="web-edges" viewBox="0 0 3000 3000" aria-hidden="true">${[460,680,900,1120,1385].map(radius=>`<circle cx="1500" cy="1500" r="${radius}"/>`).join('')}${net.edges.map(([a,b])=>{const p=lookup.get(a),q=lookup.get(b);return `<path class="${talentRank(s,a)&&talentRank(s,b)?'lit':''}" style="--edge:${TALENT_SECTORS[q.sector]?.color||TALENT_SECTORS[0].color}" d="M${p.x},${p.y} L${q.x},${q.y}"/>`;}).join('')}</svg>${net.nodes.map(n=>{const rank=talentRank(s,n.id),max=rank>=maxRank(n);return `<button class="web-node ${n.kind} ${rank?'owned':''} ${max?'maxed':''} ${this.selected===n.id?'selected':''} ${talentConnected(s,n.id,SKILLS)?'reachable':''} ${s.equipped.includes(n.id)?'equipped':''}" style="left:${n.x}px;top:${n.y}px;--sector:${TALENT_SECTORS[n.sector].color}" data-talent="${n.id}" title="${n.name} · ${max?'MÁXIMO':rank+'/'+(maxRank(n)===Infinity?'∞':maxRank(n))}" aria-label="${n.name}, ${max?'máximo':rank+' níveis'}" aria-pressed="${this.selected===n.id}">${glyph(icon(n))}${n.kind==='root'?'<b>ORIGEM</b>':`<small>${max?'✓':n.kind==='mastery'?'∞':rank||''}</small>`}${n.kind==='skill'?`<em>${n.name}</em>`:''}</button>`;}).join('')}</div></div></div><div class="web-map-legend"><span>● BÔNUS</span><span>◆ MARCO</span><span>✦ HABILIDADE</span><span class="max-mark">✓ MÁXIMO</span><span>∞ MAESTRIA</span></div></div><aside class="web-sidebar"><div id="webDetail"></div><details class="web-totals" open><summary>BÔNUS SOMADOS</summary><div id="webTotals"></div></details><div class="web-build"><b>BUILD · ${s.equipped.length}/5</b><p>${s.equipped.map(id=>SKILLS.find(k=>k.id===id).name).join(' · ')||'SEM HABILIDADES'}</p><span>⚒ ${number(power(s))} · ↯ ${movement(s)} CASAS</span></div></aside></div>`;
 }
 bind(root,s,onChange){this.root=root;this.state=s;this.onChange=onChange;const vp=root.querySelector('.web-viewport');
  const center=(x,y)=>{vp.scrollLeft=x*this.zoom-vp.clientWidth/2;vp.scrollTop=y*this.zoom-vp.clientHeight/2;};
  if(this.position){vp.scrollLeft=this.position.x;vp.scrollTop=this.position.y;}else center(1500,1500);
  root.querySelectorAll('[data-talent]').forEach(b=>b.onclick=()=>{if(this.dragged)return;this.selected=b.dataset.talent;this.detail();});
  root.querySelectorAll('[data-sector]').forEach(b=>b.onclick=()=>{const n=TALENTS.find(n=>n.ring===3&&n.sector===Number(b.dataset.sector));center(n.x,n.y);this.selected=n.id;this.detail();});
  root.querySelector('#webCenter').onclick=()=>center(1500,1500);
  root.querySelectorAll('[data-zoom]').forEach(b=>b.onclick=()=>{const x=(vp.scrollLeft+vp.clientWidth/2)/this.zoom,y=(vp.scrollTop+vp.clientHeight/2)/this.zoom;this.zoom=Math.max(.32,Math.min(1.5,this.zoom+(b.dataset.zoom==='+'?.15:-.15)));root.querySelector('.web-canvas').style.transform=`scale(${this.zoom})`;const size=root.querySelector('.web-size');size.style.width=size.style.height=TALENT_SIZE*this.zoom+'px';root.querySelector('#webZoom').textContent=Math.round(this.zoom*100)+'%';center(x,y);});
  let drag=null;vp.onpointerdown=e=>{if(e.button!==0)return;this.dragged=false;drag={x:e.clientX,y:e.clientY,sx:vp.scrollLeft,sy:vp.scrollTop};};vp.onpointermove=e=>{if(!drag)return;if(Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>7){this.dragged=true;vp.setPointerCapture(e.pointerId);}if(this.dragged){vp.scrollLeft=drag.sx-(e.clientX-drag.x);vp.scrollTop=drag.sy-(e.clientY-drag.y);}};vp.onpointerup=vp.onpointercancel=()=>{drag=null;};this.detail();
 }
 detail(){const root=this.root,s=this.state,n=talentNetwork(SKILLS).nodes.find(n=>n.id===this.selected);if(!n)return;root.querySelectorAll('[data-talent]').forEach(b=>{b.classList.toggle('selected',b.dataset.talent===n.id);b.setAttribute('aria-pressed',b.dataset.talent===n.id);});root.querySelectorAll('[data-sector]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.sector)===n.sector)));const rank=talentRank(s,n.id),max=rank>=maxRank(n),skill=n.kind==='skill',active=s.equipped.includes(n.id),editable=canRebuild(s),cost=skill?rank?skillUpgradeCost(s,n.id).points:skillPointCost(n):talentCost(s,n.id),connected=talentConnected(s,n.id,SKILLS);
  const next=n.kind==='mastery'?`+${number(.035*Math.log2((rank+2)/(rank+1))*100)}% poder no Abismo.`:skill?skillText(s,n.id,rank+1):talentText(n);
  root.querySelector('#webDetail').innerHTML=`<div class="web-selection"><div class="web-detail-icon" style="color:${TALENT_SECTORS[n.sector].color}">${glyph(icon(n))}</div><span class="web-kicker">${max?'✓ MÁXIMO':n.kind==='mastery'?'∞ MAESTRIA':n.kind==='notable'?'◆ MARCO MAIOR':skill?'✦ HABILIDADE':'● BÔNUS MENOR'}</span></div><h3>${n.name}</h3>${n.kind==='root'?'<p>ESCOLHA UM NÓ VIZINHO</p>':`<p>${skill?skillText(s,n.id):talentText(n,Math.max(1,rank))}</p><b class="web-rank">${rank} / ${maxRank(n)===Infinity?'∞':maxRank(n)}</b>${!max?`<div class="web-next"><span>PRÓXIMO</span><strong>${next}</strong></div>`:''}${!editable?'<b class="web-paused">AJUSTE NA VILA OU REFÚGIO</b>':`${!max?`<button class="primary" id="webBuy" ${s.experience.points<cost||!connected?'disabled':''}>${rank?'MELHORAR':'APRENDER'} · ✦ ${cost}</button>`:''}${skill&&rank&&!n.passive?`<button class="secondary" id="webEquip" ${!active&&s.equipped.length>=5?'disabled':''}>${active?'DESEQUIPAR':'EQUIPAR'}</button>`:''}${skill&&rank&&n.passive?'<b>SEMPRE ATIVA</b>':''}${!skill&&rank&&!s.run?'<button class="secondary" id="webRefund">DEVOLVER 1 NÍVEL</button>':''}`}${!rank&&!connected?'<p class="web-needs">ATIVE UM VIZINHO</p>':''}`}`;
  const effects=progressionEffects(s);root.querySelector('#webTotals').innerHTML=Object.entries(TALENT_EFFECTS).filter(([id])=>effects[id]>0).map(([id,def])=>`<div><span>${def.name}</span><b>+${number(effects[id]*(def.unit==='%'?100:1))}${def.unit}</b></div>`).join('')||'<p>SEM BÔNUS</p>';
  const changed=fn=>{if(!fn())return;invalidateProgression(s);progressionEffects(s);this.position={x:root.querySelector('.web-viewport').scrollLeft,y:root.querySelector('.web-viewport').scrollTop};this.onChange(n.id);};
  const buy=root.querySelector('#webBuy');if(buy)buy.onclick=()=>changed(()=>skill?rank?upgradeSkill(s,n.id):learn(s,n.id):buyTalent(s,n.id,SKILLS));const eq=root.querySelector('#webEquip');if(eq)eq.onclick=()=>changed(()=>equip(s,n.id));const refund=root.querySelector('#webRefund');if(refund)refund.onclick=()=>{if(!refundTalent(s,n.id,SKILLS)){refund.textContent='SUSTENTA OUTROS NÓS';return;}invalidateProgression(s);this.position={x:root.querySelector('.web-viewport').scrollLeft,y:root.querySelector('.web-viewport').scrollTop};this.onChange(n.id);};
 }
}

